const body = $input.first().json.body;
const required = ['customer_name', 'cancellation_reason', 'free_text_feedback'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
return [{ json: { valid: true, responseId: `CR-${Date.now()}`, customerName: body.customer_name.trim(), customerEmail: body.customer_email||'', accountTier: body.account_tier||'', monthsAsCustomer: parseInt(body.months_as_customer)||null, mrr: parseFloat(body.mrr)||null, currency: body.currency||'USD', cancellationReason: body.cancellation_reason.trim(), freeTextFeedback: body.free_text_feedback.trim().slice(0,2000), competitorSwitchedTo: body.competitor_switched_to||'', wouldRecommend: body.would_recommend!==undefined?parseInt(body.would_recommend):null, winbackInterest: body.winback_interest===true||body.winback_interest==='true', submittedAt: new Date().toISOString() } }];

