const rows = $input.all().map(r => r.json).filter(r => r.response_id);
const weekAgo = new Date(); weekAgo.setDate(weekAgo.getDate()-7);
const recent = rows.filter(r => new Date(r.submitted_at) >= weekAgo);
if (recent.length === 0) return [{ json: { hasData: false } }];
const byCategory = {};
recent.forEach(r => { byCategory[r.primary_category] = (byCategory[r.primary_category]||0)+1; });
const totalMrrLost = recent.reduce((s,r) => s + (parseFloat(r.mrr)||0), 0);
const saveable = recent.filter(r => r.save_potential==='high'||r.save_potential==='medium');
return [{ json: { hasData: true, recent, byCategory, totalMrrLost: parseFloat(totalMrrLost.toFixed(2)), currency: recent[0]?.currency||'USD', count: recent.length, saveableCount: saveable.length, weekStart: weekAgo.toISOString().split('T')[0] } }];

