const note = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Aggregate Week').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const catRows = Object.entries(d.byCategory).sort((a,b)=>b[1]-a[1]).map(([c,n]) => `<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #f3f4f6"><span style="font-size:14px">${esc(c.replace(/_/g,' '))}</span><span style="font-size:14px;font-weight:700">${n}</span></div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif"><div style="max-width:640px;margin:0 auto"><div style="background:#111827;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;color:#6b7280">Weekly Churn Digest · ${esc(d.weekStart)}</div><div style="font-size:18px;font-weight:700">${d.count} cancellations · ${d.currency}${d.totalMrrLost} MRR lost</div><div style="font-size:13px;color:#9ca3af">${d.saveableCount} flagged as saveable</div></div><div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none"><p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(note).replace(/\n/g,'<br>')}</p></div><div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">By category</div>${catRows}</div></div></body></html>`;
return [{ json: { html, count: d.count, mrrLost: d.totalMrrLost, currency: d.currency } }];
